fast_pseudocode:
# AFTER: 25 regs/thread, 100% occupancy, severe stall latency
@triton.autotune(configs=[
    Config({'XBLOCK': 128, 'YBLOCK': 8},  num_warps=4, maxnreg=32),
    Config({'XBLOCK': 256, 'YBLOCK': 16}, num_warps=8, maxnreg=32),
    # ... small-tile configs with maxnreg=32
], key=['ynumel', 'xnumel'])
@triton.jit
def kernel(...):
    # 25 regs/thread -> 16 blocks/SM -> 100% occupancy
    # BUT: Warp Cycles/Instruction = 126.26, No Eligible = 87.93%
    # L1TEX stall dominates: 62.6 cycles avg stall per instruction
    tmp = tl.load(in_ptr + offset, mask)
    tl.store(out_ptr + offset2, tmp, mask)

# AFTER: 4 configs, XBLOCK 128-1024, no maxnreg -- 894.34us (SAME, negligible difference)
@triton.autotune(configs=[
    Config({'XBLOCK': 128,  'YBLOCK': 8}, num_warps=4),
    Config({'XBLOCK': 256,  'YBLOCK': 8}, num_warps=4),
    Config({'XBLOCK': 512,  'YBLOCK': 8}, num_warps=8),
    Config({'XBLOCK': 1024, 'YBLOCK': 8}, num_warps=8),
], key=['xnumel'])
@triton.jit
def kernel(...):
    tmp = tl.load(in_ptr0 + (y0 + 512*x2 + 25690112*y1), mask)  # still non-coalesced
    tl.store(out_ptr0 + (x2 + 50176*y3), tmp, mask)
